// components/DataTable.js
import React, { useState } from 'react';

export default function DataTable({
  data = [],
  columns = [],
  searchable = false,
  searchPlaceholder = "Rechercher...",
  className = "",
  emptyMessage = "Aucune donnée disponible",
}) {
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const [itemsPerPage, setItemsPerPage] = useState(10);

  // Search functionality
  const filteredData = searchable && searchQuery
    ? data.filter(item => 
        Object.values(item).some(val => 
          val && typeof val === 'string' && val.toLowerCase().includes(searchQuery.toLowerCase())
        )
      )
    : data;

  // Pagination
  const indexOfLastItem = currentPage * itemsPerPage;
  const indexOfFirstItem = indexOfLastItem - itemsPerPage;
  const currentItems = filteredData.slice(indexOfFirstItem, indexOfLastItem);
  const totalPages = Math.ceil(filteredData.length / itemsPerPage);

  const paginate = (pageNumber) => setCurrentPage(pageNumber);

  const handleItemsPerPageChange = (e) => {
    setItemsPerPage(Number(e.target.value));
    setCurrentPage(1);
  };

  return (
    <div className={className}>
      {/* Search bar */}
      {searchable && (
        <div className="p-4 border-b border-gray-200">
          <input
            type="text"
            placeholder={searchPlaceholder}
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full p-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
          />
        </div>
      )}

      {/* Table */}
      {currentItems.length > 0 ? (
        <div className="overflow-x-auto">
          <table className="min-w-full">
            <thead className="bg-gradient-to-r from-blue-500 to-blue-600 sticky top-0">
              <tr>
                {columns.map((column) => (
                  <th key={column.id} className="p-4 text-left text-white">
                    {column.header}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {currentItems.map((row, rowIndex) => (
                <tr
                  key={rowIndex}
                  className={`border-b border-gray-100 hover:bg-gray-50 transition ${
                    rowIndex % 2 === 0 ? "bg-gray-50" : "bg-white"
                  }`}
                >
                  {columns.map((column) => (
                    <td key={`${rowIndex}-${column.id}`} className="p-4 text-gray-800">
                      {column.cell ? column.cell(row) : row[column.id]}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      ) : (
        <div className="p-8 text-center text-gray-500">{emptyMessage}</div>
      )}

      {/* Pagination */}
      {currentItems.length > 0 && (
        <div className="flex justify-between items-center p-4 bg-gradient-to-r from-blue-50 to-gray-50">
          <select
            onChange={handleItemsPerPageChange}
            value={itemsPerPage}
            className="border p-2 rounded-lg shadow-sm"
          >
            <option value={10}>10 par page</option>
            <option value={20}>20 par page</option>
            <option value={50}>50 par page</option>
          </select>
          <div className="flex space-x-2">
            {Array.from({ length: totalPages }, (_, index) => (
              <button
                key={index}
                onClick={() => paginate(index + 1)}
                className={`px-4 py-2 text-sm rounded-lg ${
                  currentPage === index + 1 ? "bg-blue-600 text-white" : "bg-white text-blue-600"
                }`}
              >
                {index + 1}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}