"use client";
import { useState, useEffect } from "react";
import axios from "axios";
import Layout from "../../components/Layout";
import DataTable from "../../components/DataTableAffect";

export default function Comptes() {
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [selectedUsers, setSelectedUsers] = useState([]);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/loginc")
      .then((response) => {
        setUsers(response.data);
        setLoading(false);
      })
      .catch(() => {
        setError("Erreur de chargement des comptes.");
        setLoading(false);
      });
  }, []);

  const sendEmail = async (email, password) => {
    try {
      await axios.post("http://localhost:5000/api/send-email", {
        email,
        subject: "Informations de Connexion à l'App",
        body: `Votre mot de passe est ${password}. Vous pouvez vous connecter en suivant ce lien: http://localhost:3000`,
      });
      alert(`Email envoyé avec succès à ${email}`);
    } catch (error) {
      alert(`Erreur lors de l'envoi de l'email à ${email}`);
    }
  };

  const sendEmailToSelected = async () => {
    try {
      for (const userId of selectedUsers) {
        const user = users.find((user) => user.id === userId);
        if (user) {
          await sendEmail(user.email, user.password);
        }
      }
      alert("Emails envoyés avec succès aux utilisateurs sélectionnés");
    } catch (error) {
      alert("Erreur lors de l'envoi des emails");
    }
  };

  const handleSelectAll = (e) => {
    if (e.target.checked) {
      setSelectedUsers(users.map((user) => user.id));
    } else {
      setSelectedUsers([]);
    }
  };

  const handleSelectUser = (userId) => {
    setSelectedUsers((prevState) =>
      prevState.includes(userId)
        ? prevState.filter((id) => id !== userId)
        : [...prevState, userId]
    );
  };

  const columns = [
    {
      header: "Sélectionner",
      accessor: "id",
      render: (id) => (
        <input
          type="checkbox"
          checked={selectedUsers.includes(id)}
          onChange={() => handleSelectUser(id)}
          className="form-checkbox h-5 w-5 text-blue-600 rounded"
        />
      ),
    },
    { header: "ID", accessor: "id" },
    { header: "ID user", accessor: "user_id" },
    { header: "Email", accessor: "email" },
    { header: "Mot de Passe", accessor: "password" },
    { header: "Rôle", accessor: "role" },
    {
      header: "Envoyer Email",
      accessor: "email",
      render: (email, row) => (
        <button
          onClick={() => sendEmail(email, row.password)}
          className="text-indigo-600 hover:text-indigo-700 font-medium"
        >
          Envoyer Email
        </button>
      ),
    },
  ];

  const tableActions = (
    <div className="flex flex-col space-y-4 md:flex-row md:space-y-0 md:space-x-4">
      <button
        onClick={sendEmailToSelected}
        className="bg-blue-600 text-white px-6 py-3 rounded-lg hover:bg-blue-700 transition duration-300 shadow-md"
      >
        Envoyer Email aux sélectionnés
      </button>
      <label className="inline-flex items-center bg-gray-100 px-4 py-3 rounded-lg">
        <input
          type="checkbox"
          onChange={handleSelectAll}
          checked={selectedUsers.length === users.length && users.length > 0}
          className="form-checkbox h-5 w-5 text-blue-600 rounded"
        />
        <span className="ml-2 text-lg text-gray-700">Sélectionner tout</span>
      </label>
    </div>
  );

  return (
    <Layout>
      <div className="w-full flex-1 py-3 px-4">
        <h1 className="text-3xl font-semibold mb-6 text-center text-gray-800">
          Liste des comptes
        </h1>

        <DataTable
          data={users}
          columns={columns}
          loading={loading}
          error={error}
          actions={tableActions}
          itemsPerPageOptions={[10, 15, 20]}
          defaultItemsPerPage={10}
          emptyMessage="Aucun compte trouvé."
          striped
          hover
        />
      </div>
    </Layout>
  );
}